import{_ as t,o as a,c as n,ah as o}from"./chunks/framework.BsNNkeaH.js";const c=JSON.parse('{"title":"App settings","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/parametres-application.md","filePath":"src/en/guide/admin/parametres-application.md"}'),s={name:"en/guide/admin/parametres-application.md"};function r(i,e,l,h,d,p){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="app-settings" tabindex="-1">App settings <a class="header-anchor" href="#app-settings" aria-label="Permalink to &quot;App settings&quot;">​</a></h1><p><strong>App settings</strong>, in the <strong>Administration</strong> space, groups everything that customises your ERA school space: its visual identity, what gets printed on receipts, and two settings that genuinely change how the app behaves for everyone else.</p><p>These apply to the whole school, not to your own account. For your personal preferences (theme, language, security), see <a href="/en/guide/prise-en-main.html">Getting started</a>.</p><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><p>The <strong>application name</strong> replaces &quot;ERA&quot; everywhere in the interface, in emails and on generated documents. It&#39;s what lets a school show its own name rather than the software&#39;s.</p><h2 id="colors" tabindex="-1">Colors <a class="header-anchor" href="#colors" aria-label="Permalink to &quot;Colors&quot;">​</a></h2><p>A <strong>primary</strong> and a <strong>secondary</strong> color, applied across the interface. The <strong>Reset</strong> button returns to ERA&#39;s defaults if an experiment doesn&#39;t work out — worth trying before hand-correcting a shade.</p><h2 id="logo" tabindex="-1">Logo <a class="header-anchor" href="#logo" aria-label="Permalink to &quot;Logo&quot;">​</a></h2><p>Two separate logos, and the difference matters:</p><ul><li>The <strong>full logo</strong> appears on the home page and the sign-in pages. It&#39;s also the one printed on the bulletins and payment receipts of any site that has no logo of its own (see <a href="/en/guide/admin/structure-etablissement.html">School structure</a>).</li><li>The <strong>icon logo</strong> appears at the top of the spaces column, on a dark blue background. If you leave it empty, the full logo is used instead — which usually becomes unreadable once scaled down. Prepare a square version that reads well on a dark background.</li></ul><h2 id="sign-in-pages" tabindex="-1">Sign-in pages <a class="header-anchor" href="#sign-in-pages" aria-label="Permalink to &quot;Sign-in pages&quot;">​</a></h2><p>The <strong>Sign-in pages</strong> section controls what families and staff see before they type anything.</p><ul><li><strong>Background image</strong> — a photo of the school, shown behind the dark blue panel on a computer, and as a band above the form on a phone. JPG, PNG or WebP, 4 MB at most. ERA washes it with blue so the text stays readable whatever the picture. Without one, the panel stays plain. <strong>Remove</strong> takes it away.</li><li><strong>Show the logo in a white tile</strong> — turn this on when your logo blends into the dark blue frame: it is then shown on a small white tile, both on the sign-in pages and inside the app. This setting only applies to <strong>your</strong> logo: ERA&#39;s own is recolored automatically and always shown bare.</li></ul><h2 id="home-page-tagline" tabindex="-1">Home page tagline <a class="header-anchor" href="#home-page-tagline" aria-label="Permalink to &quot;Home page tagline&quot;">​</a></h2><p>The homepage tagline and subtitle are no longer edited here: they joined the rest of the page&#39;s content, in <a href="/en/guide/admin/page-accueil.html">Homepage</a>.</p><h2 id="receipt-customisation" tabindex="-1">Receipt customisation <a class="header-anchor" href="#receipt-customisation" aria-label="Permalink to &quot;Receipt customisation&quot;">​</a></h2><p>These fields are printed on <strong>every generated payment receipt</strong>, alongside the logo (the student&#39;s site logo if it has one, otherwise the full logo): address, phone, email, thank-you message and footer note. These fields are shared by every site.</p><p>This is where the details a family needs on their proof of payment belong. Already-generated receipts aren&#39;t rewritten: the change applies to receipts produced afterwards.</p><h2 id="parent-self-service-linking" tabindex="-1">Parent self-service linking <a class="header-anchor" href="#parent-self-service-linking" aria-label="Permalink to &quot;Parent self-service linking&quot;">​</a></h2><p>This setting decides whether a parent can <strong>search for an already-enrolled student and link themselves</strong> to that record.</p><ul><li><strong>On</strong>: the parent does it themselves from their portal (see <a href="/en/guide/parent/enfants-et-documents.html">My children and their documents</a>).</li><li><strong>Off</strong>: the option disappears from the parent portal. Linking must then be done by the school, from the student&#39;s record (see <a href="/en/guide/admin/eleves-tuteurs.html">Students and guardians</a>).</li></ul><p>Check this setting before concluding that a parent &quot;can&#39;t find&quot; the feature: it may simply be turned off for the school.</p><h2 id="grading" tabindex="-1">Grading <a class="header-anchor" href="#grading" aria-label="Permalink to &quot;Grading&quot;">​</a></h2><p>This setting decides <strong>how a subject average combines marks from different evaluation types</strong> (assignment, exam, quiz…).</p><ul><li><strong>Off</strong> (the default): each mark counts according to its evaluation type&#39;s weight, as defined in <a href="/en/guide/admin/structure-etablissement.html">School structure</a>.</li><li><strong>On</strong>: each evaluation type counts equally, regardless of how many marks it holds. Three quizzes then don&#39;t outweigh a single exam.</li></ul><p>This is a pedagogical choice, not a display detail: it changes computed averages, and therefore report cards. Settle it before the year&#39;s first report cards are published, and avoid changing it mid-year.</p>',26)])])}const u=t(s,[["render",r]]);export{c as __pageData,u as default};
